//! capstone 5 register-access rules (see access.rs). Generated by
//! `examples/disasm_detail_diff.rs learn` from capstone's detail output, then reviewed.
//!
//! Line grammar:  MNEMONIC [COND...] = ACCESS | IMPLICIT_READ | IMPLICIT_WRITE
//!   COND     k:KINDS (operand kinds, e.g. k:rm) | s:SIG (full signature, e.g. s:r4,m4)
//!            | m32 | m64 | p:PREFIX (printed prefix: - lock rep repe repne bnd repz notrack ...)
//!            | a16 a32 a64 (address size) | o:OPC (opcode bytes [/modrm.reg], e.g. o:f6/1)
//!   ACCESS   one digit per capstone detail operand: 0 none, 1 read, 2 write, 3 read+write
//!            ("-" when there are no operands)
//!   IMPLICIT comma separated capstone register names, "flags" (eflags/rflags), "*ax".."*di" /
//!            "*ip" (native size: rax/eax, ... rip/eip)
//! The first matching rule of a mnemonic wins.

